using System;

namespace ClassLibrary1
{
    public class Calculator
    {
        public event EventHandler<CalculationEventArgs> CalculationPerformed;

        public static int Summ(int firstNumber, int secondNumber)
        {
            return firstNumber + secondNumber;
        }

        public static int Sub(int firstNumber, int secondNumber)
        {
            return firstNumber - secondNumber;
        }

        public static long Multiply(long x, long y)
        {
            return x * y;
        }

        public static double Div(double x, double y)
        {
            if (y == 0)
            {
                throw new DivideByZeroException("Деление на ноль");
            }
            return x / y;
        }

        public void Report(string operation, double result)
        {
            CalculationPerformed?.Invoke(this, new CalculationEventArgs(operation, result));
        }
    }

    public class CalculationEventArgs : EventArgs
    {
        public string Operation { get; }
        public double Result { get; }

        public CalculationEventArgs(string operation, double result)
        {
            Operation = operation;
            Result = result;
        }
    }
}

using System;

namespace ClassLibrary1
{
    public class Condenser
    {
        public const double Epsilon0 = 8.85e-12;

        public static double Capacity(double epsilon, double area, double distance)
        {
            if (distance <= 0)
            {
                throw new ArgumentException("Расстояние должно быть больше нуля");
            }
            return epsilon * Epsilon0 * area / distance;
        }
    }
}

