using System;
using System.Windows.Forms;
using ClassLibrary1;

namespace CalculatorApp
{
    public partial class Form1 : Form
    {
        private Calculator calculator = new Calculator();

        public Form1()
        {
            InitializeComponent();
            cmbOperation.Items.AddRange(new object[] { "Сложение", "Вычитание", "Умножение", "Деление" });
            cmbOperation.SelectedIndex = 0;
            calculator.CalculationPerformed += Calculator_CalculationPerformed;
        }

        private void Calculator_CalculationPerformed(object sender, CalculationEventArgs e)
        {
            lblStatus.Text = e.Operation + ": " + e.Result;
        }

        private void btnCalc_Click(object sender, EventArgs e)
        {
            int a = int.Parse(txtFirst.Text);
            int b = int.Parse(txtSecond.Text);
            double result = 0;
            switch (cmbOperation.SelectedItem.ToString())
            {
                case "Сложение":
                    result = Calculator.Summ(a, b);
                    break;
                case "Вычитание":
                    result = Calculator.Sub(a, b);
                    break;
                case "Умножение":
                    result = Calculator.Multiply(a, b);
                    break;
                case "Деление":
                    result = Calculator.Div(a, b);
                    break;
            }
            lblResult.Text = "Результат: " + result;
            calculator.Report(cmbOperation.SelectedItem.ToString(), result);
        }
    }
}

