namespace LibraryTestApp
{
    internal class Program
    {
        static void Main(string[] args)
        {
            Console.Write("Диэлектрическая проницаемость: ");
            double epsilon = double.Parse(Console.ReadLine());
            Console.Write("Площадь пластин, м2: ");
            double area = double.Parse(Console.ReadLine());
            Console.Write("Расстояние между пластинами, м: ");
            double distance = double.Parse(Console.ReadLine());
            double c = Condenser.Capacity(epsilon, area, distance);
            Console.WriteLine("Ёмкость конденсатора: " + c.ToString("E3") + " Ф");
            Console.ReadKey();
        }
    }
}
